import pandas as pd, re, collections
c=pd.read_csv('data/xd-oreo-clues-freq-1993.csv')
methods={}
def whitespace(clue): return clue.lower().split()
def alpha(clue): return re.findall(r'[a-z]+',clue.lower())
def alnum(clue): return re.findall(r'[a-z0-9]+',clue.lower())
def nopunct(clue): return re.sub(r'[^a-z0-9 ]',' ',clue.lower()).split()
for name,f in [('ws',whitespace),('alpha',alpha),('alnum',alnum),('nopunct',nopunct)]:
    cnt=collections.Counter()
    for clue,n in zip(c.clue,c['count']):
        for w in f(clue): cnt[w]+=n
    print(name, {w:cnt[w] for w in ['cookie','treat','snack','sandwich','white','black','nabisco','creme','cream','filled','popular','1912']})
# count clue once if contains
for w in ['cookie','sandwich','creme','cream']:
    print(w,'once-per-clue',c[c.clue.str.lower().str.contains(r'\b'+w+r'\b')]['count'].sum())
"

